/**
 * Returns the best matching locale from a browser language string.
 *
 * Deliberately NOT wired into the middleware. Google's multi-regional guidance
 * warns against redirecting on Accept-Language: Googlebot crawls from US IPs
 * with an English-ish header, so an automatic redirect would leave every
 * translated URL undiscoverable. Locale is chosen by the URL prefix only, and
 * visitors switch via the (crawlable) LanguageSwitcher links.
 *
 * Kept for non-navigational use — e.g. picking a default in a form or
 * suggesting a language with a dismissible banner that does not redirect.
 */
export function detectLocale(acceptLanguage: string): Locale {
  const supported = Object.keys(translations) as Locale[];
  const candidates = acceptLanguage.split(',').map((s) => s.trim().split(';')[0]!.toLowerCase());
  for (const lang of candidates) {
    const exact = supported.find((l) => l === lang);
    if (exact) return exact;
    const prefix = supported.find((l) => lang.startsWith(l));
    if (prefix) return prefix;
  }
  return 'en';
}

